The testflock program（the test program only use 500MB heap memory, the
memory used by other business processes will exceed this value）:

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/file.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <sys/syscall.h>

static inline long get_msec(void)
{
    struct timespec ts;

    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec * 1000 + ts.tv_nsec / 1000000;
}

#ifndef F_GETFD_EX
#define F_GETFD_EX	18
#endif

#ifndef F_SETFD_EX
#define F_SETFD_EX	19
#endif

#define FD_CLOBCOR	2

int main(int argc, char *argv[])
{
    size_t size_mb = 512;
	size_t size, i;
    long start = 0, stop;
    int mode = 1;

    const char *dir = "/map/zhaoxin/flock_tmp";
    int fd;
    int ret;
    char *buf;

    if (argc == 2 && strcmp(argv[1], "0") == 0) {
        printf("Do not send signal when fail!\n");
        mode = 0;
    }

    size = size_mb * 1024 * 1024;
    buf = (char*)malloc(size);
	if (!buf) {
		perror("malloc 失败");
		return 1;
	}
    for (i = 0; i < size; i++) {
        buf[i] = (char)i;
    }

    /* 打开目录，需要读权限 */
    fd = open(dir, O_CREAT | O_RDWR, 0777);
    if (fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }
    int setfd_ex_ret = fcntl(fd, F_SETFD_EX, FD_CLOBCOR);

    struct flock fl;
    fl.l_type = F_WRLCK;
    fl.l_whence = SEEK_SET;
    fl.l_start = 0;
    fl.l_len = 0;

    bool brunonce = false;
    int lastresult;

    int lock_pid = 0;

    while (1) {
        int result = fcntl(fd, F_SETLK, &fl);
        if (errno == EBADF || errno == EINVAL) {
          printf("errno=%d\n", errno);
          return -1;
        }
        if (!brunonce) {
            brunonce = true;
            // let lastresult differ from result
            lastresult = result + 1;
        }
        if (lastresult != result) {
            if (result == 0) {
                printf("get flock success!\n");
                if (start) {
                    stop = get_msec();
                    printf("waitms=%ld\n", stop - start);
                }
                while (1) {
                    sleep(1000);
                }
            }
            lastresult = result;
            if (errno == EAGAIN || errno == EACCES) {
                printf("get flock fail!\n");
                struct flock lock;
                (void)memset(&lock, 0, sizeof(lock));
                lock.l_type = F_WRLCK;
                lock.l_whence = SEEK_SET;
                lock.l_start = 0;
                lock.l_len = 0;
                if (fcntl(fd, F_GETLK, &lock) == 0) {
                    if (lock.l_type != F_UNLCK) {
                        lock_pid = lock.l_pid;

                        start = get_msec();

                        if (mode) {
                            int ret = syscall(SYS_tgkill, lock_pid, lock_pid, SIGABRT);
                        }
                        
                    }
                    printf("lock_pid=%d\n", lock_pid);
                }
            }
        }
    }

    return 0;
}

